"""Move named top-level items (with their docs and attributes) from state.rs into a new module.

usage: extract.py <new_module> <header_doc> <name>...
Names ending in '..' followed by another name form a range: `a..b` moves everything from item a through item b.
"""
import re
import sys

SRC = "src/state.rs"
ITEM = r"^(pub(\([a-z]+\))? )?(fn|const|static|struct|enum|type|impl(<[^>]*>)?) "


def find_start(lines, name):
    pat = re.compile(r"^(pub(\([a-z]+\))? )?(fn|const|static|struct|enum|type) " + re.escape(name) + r"\b")
    for i, l in enumerate(lines):
        if pat.match(l):
            return i
    raise SystemExit(f"item not found: {name}")


def find_impl(lines, header):
    for i, l in enumerate(lines):
        if l.startswith(header):
            return i
    raise SystemExit(f"impl not found: {header}")


def span(lines, start):
    top = start
    while top > 0 and re.match(r"^(///|#\[|//[^/])", lines[top - 1]):
        top -= 1
    end = start
    first = lines[start]
    if first.rstrip().endswith(";") and "{" not in first:
        return top, start
    if re.match(r"^(pub(\([a-z]+\))? )?const .*[=]\s*$", first) or (
        re.match(r"^(pub(\([a-z]+\))? )?(const|static) ", first) and not first.rstrip().endswith("{")
    ):
        while not lines[end].rstrip().endswith(";"):
            end += 1
        return top, end
    while not lines[end].startswith("}"):
        end += 1
    return top, end


def main():
    module, header = sys.argv[1], sys.argv[2]
    names = sys.argv[3:]
    lines = open(SRC).read().split("\n")
    spans = []
    for n in names:
        if n.startswith("impl "):
            start = find_impl(lines, n)
        else:
            start = find_start(lines, n)
        spans.append(span(lines, start))
    spans.sort()
    out = []
    for top, end in spans:
        out.append("\n".join(lines[top : end + 1]))
    body = "\n\n".join(out)
    body = re.sub(r"^(const|fn|static) ", r"pub(super) \1", body, flags=re.M)
    new = f"// SPDX-License-Identifier: CC0-1.0\n\n{header}\n\nuse super::*;\n\n{body}\n"
    open(f"src/state/{module}.rs", "w").write(new)
    drop = set()
    for top, end in spans:
        drop.update(range(top, end + 1))
    kept = []
    for i, l in enumerate(lines):
        if i in drop:
            continue
        kept.append(l)
    text = "\n".join(kept)
    text = re.sub(r"\n{3,}", "\n\n", text)
    open(SRC, "w").write(text)


main()

