/// The longest action name a refusal echoes back: the longest name this service has, so
/// a value no longer than any action name is reported and anything longer is not.
pub(super) const MAX_ACTION_NAME_LENGTH: usize = longest_action_name();

/// The length of the longest entry of [`ACTION_NAMES`].
pub(super) const fn longest_action_name() -> usize {
    let mut longest = 0;
    let mut index = 0;
    while index < ACTION_NAMES.len() {
        let length = ACTION_NAMES[index].len();
        if length > longest {
            longest = length;
        }
        index += 1;
    }
    longest
}

/// The statement that grants `actions` on the queue ARN `resource` to each account in
/// `account_numbers`, labelled `label`.
///
/// A member naming one value carries it alone and several as a list, which is how a
/// policy document states the two cases.
pub(super) fn permission_statement(
    label: &str,
    account_numbers: &[String],
    actions: &[String],
    resource: &str,
) -> ::serde_json::Value {
    let principals: Vec<String> = account_numbers
        .iter()
        .map(|account_number| account_principal(account_number))
----

/// Rewrite every bare-account-id principal of `document` into that account's root ARN,
/// answering whether anything changed.
fn normalise_statements(document: &mut ::serde_json::Value) -> bool {
    let Some(element) = document.get_mut("Statement") else {
        return false;
    };
    match element {
        ::serde_json::Value::Array(statements) => {
            let mut rewritten = false;
            for statement in statements.iter_mut() {
                rewritten |= normalise_statement(statement);
            }
            rewritten
        }
        statement => normalise_statement(statement),
    }
}

/// Rewrite the bare-account-id principals of ONE statement.
fn normalise_statement(statement: &mut ::serde_json::Value) -> bool {
    let mut rewritten = false;
    for element in ["Principal", "NotPrincipal"] {
        if let Some(::serde_json::Value::Object(map)) = statement.get_mut(element) {
            if let Some(aws) = map.get_mut("AWS") {
                rewritten |= normalise_account_ids(aws);
            }
        }
    }
    rewritten
}

/// Rewrite the bare account ids in one `AWS` principal value — a string or a list of them.
fn normalise_account_ids(value: &mut ::serde_json::Value) -> bool {
    match value {
        ::serde_json::Value::String(named) if is_account_id(named) => {
            *named = account_root_arn(named);
            true
        }
        ::serde_json::Value::Array(values) => {
            let mut rewritten = false;
            for value in values.iter_mut() {
                rewritten |= normalise_account_ids(value);
            }
            rewritten
        }
        _ => false,
    }
}

